import com.renkio.game.ClientStore;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class SnapshotProtocolCheck {public static void main(String[] args)throws Exception{var input=Path.of(args[0]);var lines=Files.readAllLines(Path.of(args[1]),StandardCharsets.UTF_8);List<ClientStore.Entry> entries=new ArrayList<>();for(String line:lines){String[] fields=line.split(" ",2);entries.add(new ClientStore.Entry(fields[1],fields[0],Files.readAllBytes(input.resolve(fields[1]))));}String revision=Files.readString(Path.of(args[2]),StandardCharsets.UTF_8).trim();File root=Files.createTempDirectory(Path.of(args[3]),"actual-client-").toFile();ClientStore store=new ClientStore(root);store.install(revision,entries);if(!new ClientStore(root).current().getName().equals(revision))throw new AssertionError("Snapshot did not persist");System.out.println("PASS: real server bundle verified and persisted by Android snapshot store ("+entries.size()+" files)");}}
